const TYPE_ES = { Raw: 'Bruto', Manufactured: 'Fabricado', Encoded: 'Codificado' };

/** Cuántas unidades tiene el comandante de un material (state.materials: {símbolo: cantidad}). */
const haveOf = (have, symbol) => (have && have[symbol]) || 0;
const line = (pairs, have) => pairs.map(([k, n]) => { const mt = MATS[k] || {}; const h = mt.untracked ? null : haveOf(have, k); return { key: k, name: mt.name || k, type: mt.type || null, grade: mt.grade || null, need: n, have: h, ok: mt.untracked ? true : h >= n, untracked: !!mt.untracked }; });

/**
 * Recetas de un módulo hasta el grado máximo de un ingeniero, con lo que tienes.
 * module: nombre en inglés (como en core/shipengineers.js); maxGrade: tope del ingeniero.
 */
function recipesFor(module, maxGrade, have) {
  const r = MODULE_RECIPES[module];
  if (!r) return null;
  const blueprints = r.bp.map((id) => {
    const bp = BLUEPRINTS[id];
    const grades = Object.keys(bp.g).map(Number).filter((g) => g <= (maxGrade || 5)).sort((a, b) => a - b)
      .map((g) => { const mats = line(bp.g[g], have); return { grade: g, materials: mats, ready: mats.every((x) => x.ok) }; });
    return { id, name: bp.name, merc: !!bp.merc, grades };
  });
  const specials = r.sp.map((id) => { const sp = SPECIALS[id]; const mats = line(sp.m, have); return { id, name: sp.name, materials: mats, ready: mats.every((x) => x.ok) }; });
  return { module, blueprints, specials };
}

module.exports = { MATS, BLUEPRINTS, SPECIALS, MODULE_RECIPES, TYPE_ES, recipesFor };
